func upcastswtToolBarToswtWidget(x *swt.ToolBar) *swt.Widget {
	if x == nil {
		return nil
	}
	return &x.Widget
}

func upcastArrswtToolItemToany(x []*swt.ToolItem) []any {
	if x == nil {
		return nil
	}
	r := make([]any, len(x))
	for i, e := range x {
		r[i] = e
	}
	return r
}
